CREATE TABLE anon.typed_store (entity_key LowCardinality(Nullable(String)), label_map Map(LowCardinality(String), Array(Nullable(Float64))), location Tuple(latitude Float64, longitude Float64, altitude Nullable(Int32)), mixed_value Variant(String, UInt64, Array(UInt8)), dynamic_value Dynamic(max_types = 8), payload JSON(max_dynamic_paths = 1024, user.id UInt64, SKIP internal.debug, SKIP REGEXP 'tmp_.*'), money Decimal256(20), fixed_code FixedString(3), status Enum8('active' = 1, 'paused' = 2), event_time DateTime64(9, 'UTC'), address IPv4, flag Bool) ENGINE = MergeTree ORDER BY tuple()